// System of Particles and Rotational Motion (Physics) - Question Bank
// Format follows the same schema used across the practice app:
// { id, type, question, options, correctIndex, explanation, difficulty }
// type: 'mcq' | 'assertion' | 'matching' | 'statement' | 'count'
// Note: theory-focused, with only simple/light numerical questions included, per request.

export const SYSTEM_PARTICLES_ROTATIONAL_MOTION = [

  // ============ RIGID BODY AND TYPES OF MOTION ============
  { id: 'spr-1', type: 'mcq', question: 'A body in which the distance between any two given points remains constant, regardless of any external force applied to it, is called a:', options: ['Rigid body', 'Point mass, exclusively', 'Elastic body, exclusively', 'Fluid body'], correctIndex: 0, explanation: 'A rigid body is an idealised body in which the distance between any two points remains unchanged, regardless of external forces.', difficulty: 'easy' },
  { id: 'spr-2', type: 'mcq', question: 'The motion of a rigid body in which every particle of the body has the same velocity at any given instant of time is called:', options: ['Pure translational motion', 'Pure rotational motion', 'Combined translational and rotational motion, exclusively', 'Oscillatory motion, exclusively'], correctIndex: 0, explanation: 'In pure translational motion, all particles of a rigid body move with the same velocity at any instant, and the body does not rotate.', difficulty: 'medium' },
  { id: 'spr-3', type: 'mcq', question: 'The motion of a rigid body in which every particle moves in a circle, with the centres of these circles lying on a common straight line called the axis of rotation, is called:', options: ['Pure rotational motion', 'Pure translational motion', 'Rectilinear motion, exclusively', 'Uniform motion, used interchangeably with rotational motion'], correctIndex: 0, explanation: 'In pure rotational motion, every particle of the rigid body moves in a circle around a fixed axis of rotation.', difficulty: 'medium' },
  { id: 'spr-4', type: 'mcq', question: 'Many real-world motions of rigid bodies, such as a rolling cylinder, are best described as a combination of:', options: ['Translational motion and rotational motion', 'Only translational motion, with rotation being negligible in all real cases', 'Only rotational motion, with translation being negligible in all real cases', 'Neither translational nor rotational motion, but an entirely separate category'], correctIndex: 0, explanation: 'Many practical motions, such as rolling, involve a combination of both translational and rotational motion simultaneously.', difficulty: 'medium' },
  { id: 'spr-5', type: 'assertion', question: 'Assertion (A): The concept of a rigid body is an idealisation, useful for simplifying the analysis of many real-world systems.\nReason (R): In reality, all bodies undergo at least some deformation under applied forces, but treating them as rigid (non-deforming) is a valid and useful approximation for many practical purposes in mechanics.', options: ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'], correctIndex: 0, explanation: 'The practical usefulness of the rigid body approximation, despite real materials undergoing some deformation, correctly explains why this idealisation is widely used in mechanics.', difficulty: 'medium' },

  // ============ CENTRE OF MASS ============
  { id: 'spr-6', type: 'mcq', question: 'The point at which the entire mass of a system of particles (or a rigid body) can be considered to be concentrated, for the purpose of analysing its translational motion, is called the:', options: ['Centre of mass', 'Centre of gravity, used interchangeably in every physical context without distinction', 'Axis of rotation, exclusively', 'Moment of inertia point, incorrectly named'], correctIndex: 0, explanation: 'The centre of mass is the point that represents the average position of the mass distribution of a system, useful for simplifying analysis of translational motion.', difficulty: 'easy' },
  { id: 'spr-7', type: 'mcq', question: 'For a system of two particles, the centre of mass generally lies:', options: ['Somewhere on the line joining the two particles, closer to the particle with greater mass', 'Exactly at the midpoint between the two particles, regardless of their masses', 'Outside the line joining the two particles, in every case', 'At the position of the lighter particle, always'], correctIndex: 0, explanation: 'For two particles, the centre of mass lies on the line joining them, positioned closer to the more massive particle (weighted by mass).', difficulty: 'medium' },
  { id: 'spr-8', type: 'mcq', question: 'For a system of two particles of equal mass, the centre of mass is located:', options: ['Exactly at the midpoint of the line joining them', 'Closer to one particle, depending on their relative velocities', 'Outside the line joining the two particles', 'At the position of only one of the two particles'], correctIndex: 0, explanation: 'When two particles have equal mass, their centre of mass lies exactly at the midpoint of the line joining them.', difficulty: 'medium' },
  { id: 'spr-9', type: 'mcq', question: 'The position of the centre of mass of a system of particles is NOT necessarily located:', options: ['Within the physical boundary of the material forming the body (it can lie outside a hollow or irregularly shaped object)', 'Anywhere in space, since it is purely a mathematical/geometric concept with no physical constraints', 'At a fixed location, since it can shift as the mass distribution changes', 'A meaningful point at all, for any system of particles'], correctIndex: 0, explanation: 'For hollow or irregularly shaped bodies (such as a ring or a horseshoe), the centre of mass can lie outside the actual material of the object.', difficulty: 'medium' },
  { id: 'spr-10', type: 'mcq', question: 'For a rigid body with a uniform (symmetric) mass distribution, such as a uniform sphere or a uniform rod, the centre of mass generally coincides with the body\'s:', options: ['Geometric centre', 'Outermost edge, exclusively', 'Point of maximum density, exclusively (irrelevant for uniform bodies since density is constant)', 'A randomly located point, unrelated to geometry'], correctIndex: 0, explanation: 'For symmetric bodies with uniform mass distribution, the centre of mass coincides with the geometric centre of the body.', difficulty: 'medium' },
  { id: 'spr-11', type: 'mcq', question: 'The motion of the centre of mass of a system of particles, under the influence of external forces, can be analysed as though:', options: ['The entire mass of the system were concentrated at that point, with the net external force acting there', 'It were subject to internal forces only, with external forces being irrelevant', 'Each individual particle moved completely independently, with no unifying description possible', 'It always remains stationary, regardless of any forces acting on the system'], correctIndex: 0, explanation: 'A key result is that the centre of mass of a system moves as if the entire mass of the system were concentrated there, subject to the net external force acting on the system.', difficulty: 'medium' },
  { id: 'spr-12', type: 'mcq', question: 'Internal forces between particles of a system (such as mutual attraction or collision forces between parts of the system) have what effect on the overall motion of the system\'s centre of mass?', options: ['No effect at all, since internal forces occur in equal and opposite pairs (Newton\'s Third Law) and cancel out', 'A significant effect, causing the centre of mass to accelerate independently of any external force', 'They completely determine the motion of the centre of mass, with external forces being irrelevant', 'They only affect the centre of mass when the system is in rotational motion, not translational motion'], correctIndex: 0, explanation: 'Since internal forces occur in equal and opposite action-reaction pairs (Newton\'s Third Law), they cancel out and have no net effect on the motion of the centre of mass; only external forces affect it.', difficulty: 'hard' },
  { id: 'spr-13', type: 'assertion', question: 'Assertion (A): When a shell explodes mid-air (in the absence of significant air resistance), the fragments fly off in various directions, but the centre of mass of the entire system continues to follow the same parabolic trajectory it would have followed if the explosion had not occurred.\nReason (R): The explosive forces causing the fragmentation are entirely internal to the system, and since internal forces do not affect the motion of the centre of mass, only the pre-existing external force (gravity) continues to govern its trajectory.', options: ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'], correctIndex: 0, explanation: 'The internal nature of explosive forces, and their consequent lack of effect on the centre of mass motion, correctly explains why the centre of mass continues along its original trajectory despite the explosion.', difficulty: 'hard' },
  { id: 'spr-14', type: 'count', question: 'Consider the following statements about centre of mass:\n1. For two particles of unequal mass, the centre of mass lies closer to the heavier particle.\n2. The centre of mass of a system always lies within the physical material of the system.\n3. Internal forces within a system have no effect on the motion of its centre of mass.\n4. The centre of mass of a uniform, symmetric body coincides with its geometric centre.\nHow many of the above statements are correct?', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'Statements 1, 3 and 4 are correct. Statement 2 is wrong — the centre of mass can lie outside the actual material for hollow or irregularly shaped bodies.', difficulty: 'medium' },

  // ============ VECTOR PRODUCT (CROSS PRODUCT) ============
  { id: 'spr-15', type: 'mcq', question: 'The mathematical operation between two vectors that produces a third vector, whose magnitude depends on the sine of the angle between the original two vectors, and whose direction is perpendicular to both, is called the:', options: ['Vector (cross) product', 'Scalar (dot) product', 'Vector addition, exclusively', 'Vector subtraction, exclusively'], correctIndex: 0, explanation: 'The vector (cross) product of two vectors produces a third vector, perpendicular to both original vectors, with magnitude proportional to the sine of the angle between them.', difficulty: 'medium' },
  { id: 'spr-16', type: 'mcq', question: 'The direction of the vector obtained by the cross product of two vectors is conventionally determined using the:', options: ['Right-hand rule', 'Left-hand rule, exclusively', 'Any arbitrary rule, since direction is not well-defined for cross products', 'A rule that only applies in two dimensions, not three'], correctIndex: 0, explanation: 'The right-hand rule is the standard convention used to determine the direction of the vector resulting from a cross product.', difficulty: 'medium' },
  { id: 'spr-17', type: 'mcq', question: 'Both torque and angular momentum, key concepts in rotational motion, are mathematically defined using the:', options: ['Vector (cross) product of two other vectors', 'Scalar (dot) product of two other vectors', 'Simple arithmetic addition of two other vectors', 'Simple arithmetic subtraction of two other vectors'], correctIndex: 0, explanation: 'Both torque (force × position vector) and angular momentum (position vector × linear momentum) are defined using the vector cross product.', difficulty: 'medium' },
  { id: 'spr-18', type: 'assertion', question: 'Assertion (A): The vector cross product is not commutative, unlike the vector addition and the scalar (dot) product.\nReason (R): The cross product of two vectors A and B satisfies A × B = -(B × A), meaning that reversing the order of the vectors reverses the direction of the resulting vector.', options: ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'], correctIndex: 0, explanation: 'The anti-commutative property (A × B = -B × A) correctly explains why the cross product, unlike addition or the dot product, is not commutative.', difficulty: 'hard' },

  // ============ ANGULAR VELOCITY ============
  { id: 'spr-19', type: 'mcq', question: 'The rate of change of the angular position (angle) of a rotating body with respect to time is called its:', options: ['Angular velocity', 'Linear velocity, exclusively', 'Torque, exclusively', 'Moment of inertia, exclusively'], correctIndex: 0, explanation: 'Angular velocity refers to the rate at which the angular position of a rotating body changes with time.', difficulty: 'easy' },
  { id: 'spr-20', type: 'mcq', question: 'The relationship between the linear velocity (v) of a particle at a distance r from the axis of rotation, and the angular velocity (ω) of the rotating body, is given by:', options: ['v = ω × r (vector cross product, with v perpendicular to both ω and r)', 'v = ω + r', 'v = ω/r', 'v = ω² r'], correctIndex: 0, explanation: 'The linear velocity of a particle in a rotating body is related to angular velocity by v = ω × r, a vector cross product relationship.', difficulty: 'medium' },
  { id: 'spr-21', type: 'mcq', question: 'For a rigid body rotating about a fixed axis, all particles of the body share the same:', options: ['Angular velocity, though their linear velocities may differ depending on their distance from the axis', 'Linear velocity, regardless of their distance from the axis', 'Angular velocity AND linear velocity, both being identical for every particle', 'Neither angular nor linear velocity in common, with each particle behaving completely independently'], correctIndex: 0, explanation: 'In a rigid body rotating about a fixed axis, every particle has the same angular velocity, but linear velocity varies with distance from the axis (since v = ωr).', difficulty: 'medium' },
  { id: 'spr-22', type: 'assertion', question: 'Assertion (A): Particles farther from the axis of rotation in a rotating rigid body move with greater linear speed than particles closer to the axis.\nReason (R): Since all particles of a rigid rotating body share the same angular velocity, and linear speed is given by v = ωr, particles at a greater radial distance (r) necessarily have a proportionally greater linear speed.', options: ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'], correctIndex: 0, explanation: 'The direct proportionality between linear speed and radial distance, for a fixed angular velocity, correctly explains why particles farther from the axis move faster.', difficulty: 'medium' },
  { id: 'spr-23', type: 'count', question: 'Consider the following statements about angular velocity:\n1. Angular velocity is the rate of change of angular position with time.\n2. All particles of a rigid body rotating about a fixed axis have the same angular velocity.\n3. All particles of a rigid body rotating about a fixed axis have the same linear velocity, regardless of their distance from the axis.\n4. Linear velocity is related to angular velocity by v = ω × r.\nHow many of the above statements are correct?', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'Statements 1, 2 and 4 are correct. Statement 3 is wrong — linear velocity varies with distance from the axis, even though angular velocity is the same for all particles.', difficulty: 'medium' },

  // ============ TORQUE ============
  { id: 'spr-24', type: 'mcq', question: 'The rotational analogue of force, representing the turning effect produced by a force about a given axis or point, is called:', options: ['Torque (moment of force)', 'Angular momentum, exclusively', 'Moment of inertia, exclusively', 'Angular velocity, exclusively'], correctIndex: 0, explanation: 'Torque, also called the moment of force, represents the rotational (turning) effect of a force about a specific axis or point.', difficulty: 'easy' },
  { id: 'spr-25', type: 'mcq', question: 'Torque (τ) is mathematically defined as the vector (cross) product of the position vector (r) of the point of application of the force, and the force (F) itself:', options: ['τ = r × F', 'τ = r + F', 'τ = r · F (dot product)', 'τ = r/F'], correctIndex: 0, explanation: 'Torque is defined as the cross product of the position vector r (from the axis/pivot to the point of force application) and the force F itself.', difficulty: 'medium' },
  { id: 'spr-26', type: 'mcq', question: 'For a given magnitude of applied force, the torque produced about a pivot is maximised when the force is applied:', options: ['Perpendicular to the position vector (i.e., perpendicular to the line from the pivot to the point of application)', 'Parallel to the position vector', 'At a very small distance from the pivot, regardless of angle', 'In a direction that produces zero displacement of the point of application'], correctIndex: 0, explanation: 'Since torque involves the sine of the angle between force and position vector, torque is maximised when this angle is 90° (force perpendicular to the position vector).', difficulty: 'medium' },
  { id: 'spr-27', type: 'mcq', question: 'When the applied force acts exactly along the line of the position vector (i.e., directly towards or away from the pivot point), the resulting torque about that pivot is:', options: ['Zero', 'Maximum possible for that force magnitude', 'Undefined, requiring further information', 'Always negative'], correctIndex: 0, explanation: 'When force is applied along the same line as the position vector (angle of 0° or 180°), the resulting torque is zero, since sine of 0° or 180° is zero.', difficulty: 'medium' },
  { id: 'spr-28', type: 'mcq', question: 'A door is typically designed with its handle placed far from the hinges (rather than close to them) because:', options: ['This maximises the moment arm (perpendicular distance), allowing a smaller applied force to produce a sufficient torque to open the door', 'This minimises the applied torque needed, which is undesirable and should generally be avoided', 'The position of the handle has no effect whatsoever on the ease of opening the door', 'It is purely an aesthetic design choice, with no functional or physical justification'], correctIndex: 0, explanation: 'Placing the handle far from the hinges maximises the moment arm, so a relatively small applied force produces sufficient torque to open the door.', difficulty: 'medium' },
  { id: 'spr-29', type: 'assertion', question: 'Assertion (A): It is easier to loosen a tight nut using a long wrench compared to a short one.\nReason (R): For the same applied force, a longer wrench provides a greater moment arm (perpendicular distance from the pivot to the line of force), resulting in greater torque and making it easier to loosen the nut.', options: ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'], correctIndex: 0, explanation: 'The greater moment arm provided by a longer wrench, resulting in greater torque for the same applied force, correctly explains why long wrenches make loosening nuts easier.', difficulty: 'medium' },
  { id: 'spr-30', type: 'count', question: 'Consider the following statements about torque:\n1. Torque is defined as the cross product of the position vector and the force vector.\n2. Torque is maximum when the force is applied along the position vector.\n3. Torque is zero when force is applied perpendicular to the position vector.\n4. A longer moment arm generally produces greater torque for the same applied force.\nHow many of the above statements are correct?', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 1, explanation: 'Statements 1 and 4 are correct. Statement 2 is wrong (torque is zero, not maximum, when force is along the position vector), and statement 3 is wrong (torque is maximum, not zero, when force is perpendicular to the position vector).', difficulty: 'medium' },

  // ============ ANGULAR MOMENTUM ============
  { id: 'spr-31', type: 'mcq', question: 'The rotational analogue of linear momentum, representing the quantity of rotational motion possessed by a particle or rigid body, is called:', options: ['Angular momentum', 'Torque, exclusively', 'Moment of inertia, exclusively', 'Angular velocity, exclusively'], correctIndex: 0, explanation: 'Angular momentum is the rotational counterpart of linear momentum, representing the quantity of rotational motion of a particle or body.', difficulty: 'easy' },
  { id: 'spr-32', type: 'mcq', question: 'Angular momentum (L) of a particle, about a chosen origin, is defined as the vector (cross) product of its position vector (r) and its linear momentum (p):', options: ['L = r × p', 'L = r + p', 'L = r · p (dot product)', 'L = r/p'], correctIndex: 0, explanation: 'Angular momentum is defined as the cross product of the position vector r and the linear momentum p of the particle.', difficulty: 'medium' },
  { id: 'spr-33', type: 'mcq', question: 'The rate of change of angular momentum of a system, with respect to time, is equal to:', options: ['The net external torque acting on the system', 'The net linear momentum of the system, exclusively', 'A constant value, always, regardless of any applied torque', 'Zero, in every possible physical scenario'], correctIndex: 0, explanation: 'A fundamental result in rotational mechanics states that the rate of change of angular momentum equals the net external torque acting on the system, analogous to Newton\'s Second Law for linear motion.', difficulty: 'medium' },
  { id: 'spr-34', type: 'assertion', question: 'Assertion (A): The relationship between torque and angular momentum is analogous to the relationship between force and linear momentum in Newton\'s Second Law.\nReason (R): Just as net force equals the rate of change of linear momentum, net torque equals the rate of change of angular momentum, establishing a parallel structure between translational and rotational dynamics.', options: ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'], correctIndex: 0, explanation: 'The parallel mathematical structure between force-momentum and torque-angular momentum relationships correctly explains the described analogy.', difficulty: 'medium' },

  // ============ CONSERVATION OF ANGULAR MOMENTUM ============
  { id: 'spr-35', type: 'mcq', question: 'In the absence of any net external torque acting on a system, the total angular momentum of that system:', options: ['Remains constant (conserved)', 'Continuously increases', 'Continuously decreases', 'Becomes zero immediately'], correctIndex: 0, explanation: 'The Law of Conservation of Angular Momentum states that, in the absence of a net external torque, the total angular momentum of a system remains constant.', difficulty: 'medium' },
  { id: 'spr-36', type: 'mcq', question: 'A classic illustration of the conservation of angular momentum is observed when an ice skater, initially spinning with arms outstretched, pulls their arms in close to their body, causing their spin rate to:', options: ['Increase, as their moment of inertia decreases', 'Decrease, as their moment of inertia decreases', 'Remain exactly the same, regardless of arm position', 'Become zero immediately, regardless of arm position'], correctIndex: 0, explanation: 'As the skater pulls their arms in, their moment of inertia decreases; since angular momentum (L = Iω) is conserved, angular velocity (spin rate) must increase to compensate.', difficulty: 'medium' },
  { id: 'spr-37', type: 'assertion', question: 'Assertion (A): A diver performing a somersault can increase their rate of spin by curling their body into a tighter, more compact shape.\nReason (R): By reducing their moment of inertia through curling, the diver\'s angular velocity increases (since angular momentum is conserved in the absence of external torque during the airborne phase), resulting in a faster spin rate.', options: ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'], correctIndex: 0, explanation: 'The conservation of angular momentum, combined with the reduction in moment of inertia when curling, correctly explains the increased spin rate observed in diving/gymnastics.', difficulty: 'medium' },
  { id: 'spr-38', type: 'count', question: 'Consider the following statements about conservation of angular momentum:\n1. Angular momentum is conserved in the absence of a net external torque.\n2. When a spinning skater pulls their arms in, their moment of inertia decreases.\n3. According to conservation of angular momentum, the skater\'s angular velocity decreases as their moment of inertia decreases.\n4. Angular momentum conservation is analogous to linear momentum conservation, in the sense that both apply when the corresponding net "cause" (torque or force) is absent.\nHow many of the above statements are correct?', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'Statements 1, 2 and 4 are correct. Statement 3 is wrong — angular velocity increases (not decreases) as moment of inertia decreases, to keep angular momentum constant.', difficulty: 'medium' },

  // ============ EQUILIBRIUM OF A RIGID BODY ============
  { id: 'spr-39', type: 'mcq', question: 'A rigid body is said to be in mechanical equilibrium when it satisfies which of the following conditions?', options: ['Both the net external force and the net external torque acting on it are zero', 'Only the net external force is zero, with torque being irrelevant', 'Only the net external torque is zero, with force being irrelevant', 'Neither force nor torque needs to be zero, as long as the body appears stationary'], correctIndex: 0, explanation: 'A rigid body is in complete mechanical equilibrium when both the net external force (ensuring translational equilibrium) and the net external torque (ensuring rotational equilibrium) are zero.', difficulty: 'medium' },
  { id: 'spr-40', type: 'mcq', question: 'The condition in which the net external force on a rigid body is zero, ensuring that the body does not undergo linear (translational) acceleration, is called:', options: ['Translational equilibrium', 'Rotational equilibrium, exclusively', 'Angular equilibrium, used interchangeably with translational equilibrium', 'Static equilibrium, used exclusively in a different, unrelated context'], correctIndex: 0, explanation: 'Translational equilibrium refers to the condition where the net external force on a body is zero, preventing linear acceleration.', difficulty: 'medium' },
  { id: 'spr-41', type: 'mcq', question: 'The condition in which the net external torque on a rigid body is zero, ensuring that the body does not undergo angular acceleration, is called:', options: ['Rotational equilibrium', 'Translational equilibrium, exclusively', 'Linear equilibrium, used interchangeably with rotational equilibrium', 'Kinetic equilibrium, used exclusively in a different, unrelated context'], correctIndex: 0, explanation: 'Rotational equilibrium refers to the condition where the net external torque on a body is zero, preventing angular acceleration.', difficulty: 'medium' },
  { id: 'spr-42', type: 'mcq', question: 'It is possible for a rigid body to be in translational equilibrium (net force zero) while NOT being in rotational equilibrium; this occurs when the applied forces are such that they:', options: ['Cancel out in terms of net force but still produce a net non-zero torque about some point', 'Both cancel out completely, in both force and torque, making rotational equilibrium unavoidable', 'Are all applied at exactly the same single point, always resulting in rotational equilibrium as well', 'Are always parallel to each other, guaranteeing rotational equilibrium in every case'], correctIndex: 0, explanation: 'Forces can sum to zero (translational equilibrium) while still producing a net torque about some axis (e.g., in the case of a "couple"), resulting in rotational disequilibrium.', difficulty: 'hard' },
  { id: 'spr-43', type: 'mcq', question: 'A pair of equal and opposite forces, acting on a rigid body along different (parallel but non-collinear) lines of action, resulting in a net force of zero but a non-zero net torque, is called a:', options: ['Couple', 'Balanced force pair, incorrectly labelled since it produces rotation', 'Null force system, incorrectly labelled since torque is non-zero', 'Concurrent force system, incorrectly categorised'], correctIndex: 0, explanation: 'A couple consists of two equal, opposite, and non-collinear forces, which produce a net torque despite having zero net force — a classic example of translational equilibrium without rotational equilibrium.', difficulty: 'medium' },
  { id: 'spr-44', type: 'assertion', question: 'Assertion (A): Turning a steering wheel or a screwdriver involves applying a couple.\nReason (R): In both cases, equal and opposite forces are typically applied at different points (e.g., opposite sides of the wheel or handle), resulting in zero net force but a non-zero net torque that produces rotation.', options: ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'], correctIndex: 0, explanation: 'The application of equal, opposite, non-collinear forces in these everyday actions correctly illustrates and explains the concept of a couple as described in the assertion.', difficulty: 'medium' },
  { id: 'spr-45', type: 'count', question: 'Consider the following statements about equilibrium of a rigid body:\n1. Translational equilibrium requires zero net external force.\n2. Rotational equilibrium requires zero net external torque.\n3. A body in translational equilibrium is automatically also in rotational equilibrium, in every case.\n4. A couple produces zero net force but a non-zero net torque.\nHow many of the above statements are correct?', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'Statements 1, 2 and 4 are correct. Statement 3 is wrong — translational equilibrium does not guarantee rotational equilibrium, as illustrated by the case of a couple.', difficulty: 'medium' },
  { id: 'spr-46', type: 'matching', question: 'Match Column I (equilibrium concept) with Column II (condition):\nColumn I: A. Translational equilibrium  B. Rotational equilibrium  C. Couple\nColumn II: i. Zero net force, non-zero net torque  ii. Zero net external force  iii. Zero net external torque', options: ['A-ii, B-iii, C-i', 'A-i, B-ii, C-iii', 'A-iii, B-i, C-ii', 'A-ii, B-i, C-iii'], correctIndex: 0, explanation: 'Translational equilibrium — zero net force; Rotational equilibrium — zero net torque; Couple — zero net force but non-zero net torque.', difficulty: 'medium' },

  // ============ MOMENT OF INERTIA ============
  { id: 'spr-47', type: 'mcq', question: 'The rotational analogue of mass, representing a body\'s resistance to angular acceleration about a given axis, is called:', options: ['Moment of inertia', 'Angular momentum, exclusively', 'Torque, exclusively', 'Radius of gyration, exclusively'], correctIndex: 0, explanation: 'Moment of inertia is the rotational analogue of mass, quantifying a body\'s resistance to changes in its rotational motion about a given axis.', difficulty: 'easy' },
  { id: 'spr-48', type: 'mcq', question: 'The moment of inertia of a rigid body about a given axis depends on both the total mass of the body and:', options: ['The distribution of that mass relative to the axis of rotation', 'The colour of the body, exclusively', 'The temperature of the body, exclusively', 'The chemical composition of the body, exclusively, unrelated to mass distribution'], correctIndex: 0, explanation: 'Moment of inertia depends not just on total mass, but crucially on how that mass is distributed relative to the axis of rotation.', difficulty: 'medium' },
  { id: 'spr-49', type: 'mcq', question: 'For a given total mass, a body with its mass concentrated farther from the axis of rotation has, compared to a body with mass concentrated closer to the axis:', options: ['A greater moment of inertia', 'A smaller moment of inertia', 'Exactly the same moment of inertia, since total mass is the only factor', 'An undefined moment of inertia, since distribution has no bearing on this quantity'], correctIndex: 0, explanation: 'Since moment of inertia depends on the distribution of mass (specifically, the square of the distance from the axis), mass concentrated farther from the axis results in a greater moment of inertia.', difficulty: 'medium' },
  { id: 'spr-50', type: 'mcq', question: 'A larger moment of inertia about a given axis implies that a body:', options: ['Requires a greater torque to produce a given angular acceleration about that axis', 'Requires a smaller torque to produce the same angular acceleration', 'Cannot be rotated at all, regardless of the applied torque', 'Has no rotational inertia whatsoever'], correctIndex: 0, explanation: 'A greater moment of inertia indicates greater resistance to angular acceleration, requiring a larger torque to produce the same angular acceleration compared to a body with smaller moment of inertia.', difficulty: 'medium' },
  { id: 'spr-51', type: 'assertion', question: 'Assertion (A): It is more difficult to change the rotational state of a solid disc than a ring of the same mass and radius, rotating about the same central axis.\nReason (R): A ring has all of its mass concentrated at the maximum possible distance from the axis (the rim), giving it a larger moment of inertia than a solid disc of the same mass and radius, where mass is distributed throughout the interior as well.', options: ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'], correctIndex: 0, explanation: 'The concentration of mass at the rim in a ring, versus its distribution throughout a disc, correctly explains why a ring has a larger moment of inertia and is thus harder to rotationally accelerate/decelerate.', difficulty: 'hard' },
  { id: 'spr-52', type: 'count', question: 'Consider the following statements about moment of inertia:\n1. It is the rotational analogue of mass.\n2. It depends only on the total mass of the body, and not on how that mass is distributed.\n3. A greater moment of inertia means greater resistance to angular acceleration.\n4. A ring has a greater moment of inertia than a solid disc of the same mass and radius, about the central axis.\nHow many of the above statements are correct?', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'Statements 1, 3 and 4 are correct. Statement 2 is wrong — moment of inertia depends critically on mass distribution, not just total mass.', difficulty: 'medium' },

  // ============ THEOREMS OF PARALLEL AND PERPENDICULAR AXES ============
  { id: 'spr-53', type: 'mcq', question: 'The theorem that relates the moment of inertia of a planar (flat) body about an axis perpendicular to its plane, to the moments of inertia about two mutually perpendicular axes lying within the plane and intersecting at the same point, is called the:', options: ['Theorem of perpendicular axes', 'Theorem of parallel axes', 'Conservation of angular momentum theorem, incorrectly named here', 'Torque-angular momentum theorem, incorrectly named here'], correctIndex: 0, explanation: 'The theorem of perpendicular axes applies specifically to planar bodies, relating the moment of inertia about an axis perpendicular to the plane to those about two perpendicular in-plane axes.', difficulty: 'medium' },
  { id: 'spr-54', type: 'mcq', question: 'The theorem that relates the moment of inertia of a body about any given axis, to its moment of inertia about a parallel axis passing through its centre of mass, is called the:', options: ['Theorem of parallel axes', 'Theorem of perpendicular axes', 'Newton\'s theorem of inertia, incorrectly named here', 'Conservation theorem, incorrectly named here'], correctIndex: 0, explanation: 'The theorem of parallel axes relates the moment of inertia about any axis to the moment of inertia about a parallel axis through the centre of mass, plus a term involving the mass and the distance between the axes.', difficulty: 'medium' },
  { id: 'spr-55', type: 'mcq', question: 'According to the theorem of parallel axes, the moment of inertia (I) of a body about any axis is given by I = Icm + Md², where Icm is the moment of inertia about a parallel axis through the centre of mass, M is the total mass, and d represents:', options: ['The perpendicular distance between the two parallel axes', 'The total length of the body', 'The angular velocity of the body', 'The radius of gyration of the body about the centre of mass axis, exclusively'], correctIndex: 0, explanation: 'In the parallel axis theorem, d represents the perpendicular distance between the given axis and the parallel axis through the centre of mass.', difficulty: 'medium' },
  { id: 'spr-56', type: 'mcq', question: 'According to the theorem of parallel axes, the moment of inertia of a body about any axis is always:', options: ['Greater than or equal to its moment of inertia about a parallel axis through the centre of mass', 'Less than or equal to its moment of inertia about a parallel axis through the centre of mass', 'Exactly equal to its moment of inertia about a parallel axis through the centre of mass, in every case', 'Unrelated to its moment of inertia about a parallel axis through the centre of mass'], correctIndex: 0, explanation: 'Since the additional term (Md²) in the parallel axis theorem is always non-negative, the moment of inertia about any axis is always greater than or equal to the moment of inertia about the parallel centre-of-mass axis.', difficulty: 'medium' },
  { id: 'spr-57', type: 'mcq', question: 'The theorem of perpendicular axes applies specifically and exclusively to:', options: ['Planar (flat, two-dimensional) laminar bodies', 'Any three-dimensional body, without restriction', 'Only spherical bodies', 'Only bodies with a hollow, ring-like structure'], correctIndex: 0, explanation: 'The theorem of perpendicular axes applies specifically to planar (laminar) bodies, i.e., bodies that can be treated as effectively two-dimensional/flat.', difficulty: 'medium' },
  { id: 'spr-58', type: 'assertion', question: 'Assertion (A): The theorem of parallel axes is a useful tool for calculating moments of inertia about various axes without repeating complex integration for each case.\nReason (R): Once the moment of inertia about an axis through the centre of mass is known (often available from standard results), the theorem allows quick calculation of the moment of inertia about any parallel axis, using only the mass and the distance between the axes.', options: ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'], correctIndex: 0, explanation: 'The simplicity of applying the theorem, once the centre-of-mass moment of inertia is known, correctly explains its practical usefulness as described in the assertion.', difficulty: 'medium' },
  { id: 'spr-59', type: 'count', question: 'Consider the following statements about the theorems of parallel and perpendicular axes:\n1. The theorem of perpendicular axes applies specifically to planar (flat) bodies.\n2. The theorem of parallel axes relates moment of inertia about any axis to that about a parallel centre-of-mass axis.\n3. According to the parallel axis theorem, moment of inertia about any axis is always less than that about the parallel centre-of-mass axis.\n4. The theorem of parallel axes applies to bodies of any shape, not just planar ones.\nHow many of the above statements are correct?', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'Statements 1, 2 and 4 are correct. Statement 3 is wrong — moment of inertia about any axis is always greater than or equal to (never less than) that about the parallel centre-of-mass axis.', difficulty: 'hard' },
  { id: 'spr-60', type: 'matching', question: 'Match Column I (theorem) with Column II (applicability/formula):\nColumn I: A. Parallel axis theorem  B. Perpendicular axis theorem\nColumn II: i. Applies specifically to planar bodies  ii. I = Icm + Md², applies to any rigid body', options: ['A-ii, B-i', 'A-i, B-ii', 'Both apply only to planar bodies', 'Both apply only to three-dimensional bodies'], correctIndex: 0, explanation: 'Parallel axis theorem — I = Icm + Md², applies generally; Perpendicular axis theorem — applies specifically to planar bodies.', difficulty: 'medium' },

  // ============ KINEMATICS AND DYNAMICS OF ROTATIONAL MOTION ============
  { id: 'spr-61', type: 'mcq', question: 'The equations of rotational kinematics for a body undergoing motion with uniform (constant) angular acceleration are directly analogous to the equations of linear motion, with angular displacement, angular velocity, and angular acceleration replacing:', options: ['Linear displacement, linear velocity and linear acceleration respectively', 'Mass, force and torque respectively', 'Time, distance and speed respectively, in an unrelated substitution', 'Energy, work and power respectively, in an unrelated substitution'], correctIndex: 0, explanation: 'The rotational kinematic equations mirror the linear kinematic equations, with angular quantities (θ, ω, α) directly analogous to their linear counterparts (s, v, a).', difficulty: 'medium' },
  { id: 'spr-62', type: 'mcq', question: 'The rotational analogue of Newton\'s Second Law (F = ma), applicable to a rigid body rotating about a fixed axis, is expressed as:', options: ['τ = Iα (torque equals moment of inertia times angular acceleration)', 'τ = Iv (torque equals moment of inertia times linear velocity)', 'F = Iα (force equals moment of inertia times angular acceleration)', 'τ = ma (torque equals mass times linear acceleration)'], correctIndex: 0, explanation: 'The rotational analogue of Newton\'s Second Law is τ = Iα, where τ is net torque, I is moment of inertia, and α is angular acceleration.', difficulty: 'medium' },
  { id: 'spr-63', type: 'mcq', question: 'The rotational kinetic energy of a rigid body rotating about a fixed axis with angular velocity ω and moment of inertia I is given by:', options: ['KE(rotational) = (1/2)Iω²', 'KE(rotational) = Iω', 'KE(rotational) = (1/2)Iω', 'KE(rotational) = Iω²'], correctIndex: 0, explanation: 'The rotational kinetic energy formula, KE = (1/2)Iω², is directly analogous to the translational kinetic energy formula (1/2)mv², with I replacing m and ω replacing v.', difficulty: 'medium' },
  { id: 'spr-64', type: 'assertion', question: 'Assertion (A): The analogy between linear and rotational dynamics (e.g., F ↔ τ, m ↔ I, v ↔ ω, a ↔ α) is a useful conceptual tool for understanding rotational motion.\nReason (R): Since the mathematical structure of rotational equations closely mirrors that of linear motion equations, this analogy allows learners to apply familiar concepts from translational mechanics to rotational scenarios.', options: ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'], correctIndex: 0, explanation: 'The parallel mathematical structure between linear and rotational dynamics correctly explains the pedagogical usefulness of this analogy, as stated in the assertion.', difficulty: 'medium' },
  { id: 'spr-65', type: 'count', question: 'Consider the following statements about rotational dynamics:\n1. τ = Iα is the rotational analogue of F = ma.\n2. Rotational kinetic energy is given by (1/2)Iω².\n3. The rotational kinematic equations are unrelated to the linear kinematic equations.\n4. Angular momentum is the rotational analogue of linear momentum.\nHow many of the above statements are correct?', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'Statements 1, 2 and 4 are correct. Statement 3 is wrong — the rotational kinematic equations are directly analogous to (not unrelated to) the linear kinematic equations.', difficulty: 'medium' },

  // ============ ROLLING MOTION ============
  { id: 'spr-66', type: 'mcq', question: 'Rolling motion, such as that of a wheel or ball moving along a surface, is generally described as a combination of:', options: ['Translational motion of the centre of mass and rotational motion about the centre of mass', 'Purely translational motion, with no rotational component involved', 'Purely rotational motion, with no translational component involved', 'Neither translational nor rotational motion, but an entirely different, third category of motion'], correctIndex: 0, explanation: 'Rolling motion is described as a superposition of translational motion of the centre of mass and rotational motion about an axis through the centre of mass.', difficulty: 'medium' },
  { id: 'spr-67', type: 'mcq', question: 'For an object undergoing pure rolling motion without slipping, the velocity of the point of contact between the object and the surface it is rolling on is:', options: ['Zero (relative to the surface)', 'Equal to the velocity of the centre of mass', 'Equal to twice the velocity of the centre of mass', 'Undefined, since rolling motion has no well-defined point of contact velocity'], correctIndex: 0, explanation: 'A defining characteristic of rolling without slipping is that the instantaneous velocity of the point of contact (relative to the surface) is zero.', difficulty: 'medium' },
  { id: 'spr-68', type: 'mcq', question: 'For pure rolling motion without slipping, the relationship between the linear speed (v) of the centre of mass and the angular speed (ω) of the rolling object of radius R is given by:', options: ['v = ωR', 'v = ω/R', 'v = ωR²', 'v = ω + R'], correctIndex: 0, explanation: 'For rolling without slipping, the linear speed of the centre of mass is related to the angular speed by v = ωR, where R is the radius of the rolling object.', difficulty: 'medium' },
  { id: 'spr-69', type: 'mcq', question: 'The total kinetic energy of a rolling body (without slipping) is the sum of its:', options: ['Translational kinetic energy and rotational kinetic energy', 'Only its translational kinetic energy, with no rotational contribution', 'Only its rotational kinetic energy, with no translational contribution', 'Potential energy and translational kinetic energy, exclusively'], correctIndex: 0, explanation: 'The total kinetic energy of a rolling object combines both translational kinetic energy (due to centre-of-mass motion) and rotational kinetic energy (due to spinning motion).', difficulty: 'medium' },
  { id: 'spr-70', type: 'assertion', question: 'Assertion (A): Different rolling objects (such as a solid sphere, a hollow sphere, a solid cylinder, and a hollow cylinder) of the same mass and radius, released from rest on the same inclined plane, generally reach the bottom at different times.\nReason (R): Since these objects have different moments of inertia (due to different mass distributions), they have different proportions of their total kinetic energy allocated to rotational versus translational motion, resulting in different linear accelerations down the incline.', options: ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'], correctIndex: 0, explanation: 'The differing moments of inertia (and hence differing energy partition between translation and rotation) correctly explain why different rolling objects reach the bottom of an incline at different times, despite having equal mass and radius.', difficulty: 'hard' },
  { id: 'spr-71', type: 'count', question: 'Consider the following statements about rolling motion:\n1. Rolling motion combines translational and rotational motion.\n2. For rolling without slipping, the point of contact has zero velocity relative to the surface.\n3. The relationship v = ωR applies to rolling without slipping.\n4. All rolling objects of the same mass and radius, regardless of shape/mass distribution, take exactly the same time to roll down a given incline from rest.\nHow many of the above statements are correct?', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'Statements 1, 2 and 3 are correct. Statement 4 is wrong — objects with different moments of inertia (due to different mass distributions) take different times to roll down the same incline, even with equal mass and radius.', difficulty: 'medium' },
  { id: 'spr-72', type: 'statement', question: 'Statement I: A hollow sphere and a solid sphere of the same mass and radius have different moments of inertia about their central axis.\nStatement II: This is because a hollow sphere has its mass concentrated farther from the axis (at the outer shell), giving it a larger moment of inertia than a solid sphere of the same mass and radius, where mass is distributed throughout the interior.\nIn light of the above statements, choose the most appropriate answer:', options: ['Both Statement I and Statement II are correct, and Statement II correctly explains the difference described in Statement I', 'Both statements are correct but unrelated', 'Statement I is correct, Statement II is incorrect', 'Statement I is incorrect, Statement II is correct'], correctIndex: 0, explanation: 'The differing mass distribution between a hollow and solid sphere (Statement II) correctly explains why their moments of inertia differ, as described in Statement I.', difficulty: 'hard' },

  // ============ MIXED / REVISION ============
  { id: 'spr-73', type: 'mcq', question: 'Which of the following pairs is INCORRECTLY matched (linear quantity and its rotational analogue)?', options: ['Mass — Moment of inertia', 'Force — Torque', 'Linear momentum — Angular momentum', 'Linear velocity — Angular momentum'], correctIndex: 3, explanation: 'The correct rotational analogue of linear velocity (v) is angular velocity (ω), not angular momentum.', difficulty: 'medium' },
  { id: 'spr-74', type: 'mcq', question: 'Which of the following best summarises the overall structure of this chapter?', options: ['It extends the concepts of linear (translational) mechanics — force, momentum, kinetic energy — to describe the rotational motion of extended, rigid bodies, using analogous quantities like torque, angular momentum and moment of inertia', 'It focuses exclusively on the motion of single point particles, with no consideration of extended bodies', 'It is entirely unrelated to concepts covered in previous mechanics chapters', 'It deals only with fluid systems, not rigid bodies'], correctIndex: 0, explanation: 'The chapter systematically extends translational mechanics concepts to rotational motion of rigid bodies, introducing rotational analogues of familiar linear quantities.', difficulty: 'medium' },
  { id: 'spr-75', type: 'assertion', question: 'Assertion (A): Understanding the concept of moment of inertia is essential for analysing the rotational dynamics of any rigid body.\nReason (R): Just as mass determines a body\'s resistance to linear acceleration under an applied force, moment of inertia determines a body\'s resistance to angular acceleration under an applied torque, making it a foundational quantity in rotational mechanics.', options: ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'], correctIndex: 0, explanation: 'The direct analogy between mass (linear inertia) and moment of inertia (rotational inertia) correctly explains why moment of inertia is a foundational, essential concept for rotational dynamics.', difficulty: 'medium' },
  { id: 'spr-76', type: 'count', question: 'Consider the following statements summarising the chapter:\n1. Centre of mass motion depends only on external forces, not internal forces.\n2. Torque is the rotational analogue of force, and angular momentum is the rotational analogue of linear momentum.\n3. The parallel and perpendicular axes theorems help simplify moment of inertia calculations.\n4. Rolling motion involves either translational or rotational motion exclusively, never both simultaneously.\nHow many of the above statements are correct?', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'Statements 1, 2 and 3 are correct. Statement 4 is wrong — rolling motion is specifically a combination of both translational and rotational motion occurring simultaneously.', difficulty: 'medium' },
  { id: 'spr-77', type: 'statement', question: 'Statement I: The conservation of angular momentum is a general physical principle, applicable whenever the net external torque on a system is zero.\nStatement II: This principle explains a variety of phenomena, from the spin rate changes of ice skaters and divers to the orbital dynamics of planets and rotating astronomical objects.\nIn light of the above statements, choose the most appropriate answer:', options: ['Both Statement I and Statement II are correct', 'Both Statement I and Statement II are incorrect', 'Statement I is correct but Statement II is incorrect', 'Statement I is incorrect but Statement II is correct'], correctIndex: 0, explanation: 'Both statements correctly describe the general applicability of angular momentum conservation and its relevance across a broad range of physical phenomena.', difficulty: 'medium' },
];
